// Extraer posts del body y preparar prompt para clasificación
const body = $input.first().json.body;
const posts = body.posts || [];

if (!posts.length) {
  return [{ json: { error: 'No posts received', classified: [] } }];
}

// Construir prompt con los posts para clasificación batch
const postsSummary = posts.map((p, i) => {
  const caption = (p.caption || '').substring(0, 300);
  return `[${i}] id=${p.id} | type=${p.media_type} | caption="${caption}" | permalink=${p.permalink}`;
}).join('\n');

const prompt = `Eres un clasificador de publicaciones de Instagram para una plataforma de e-commerce chilena.

Clasifica cada publicación en una de estas categorías:
- "product": Es un producto real a la venta (ropa, electrónica, comida, servicios, etc.)
- "ad": Es publicidad, promoción genérica o spam
- "personal": Es contenido personal, selfie, evento, viaje
- "catalog": Es un catálogo o collage de múltiples productos
- "other": Meme, repost, contenido no clasificable

Para cada post clasificado como "product", extrae:
- name: nombre corto del producto (inferido del caption)
- price: precio en CLP si se menciona (solo número, null si no hay)
- description: descripción breve del producto
- brand: marca si se menciona (null si no)
- category: categoría general (Ropa, Electrónica, Alimentos, Belleza, Hogar, Servicios, Otro)

Publicaciones a clasificar:
${postsSummary}

Responde SOLO con un JSON array. Cada elemento:
{"index": N, "classification": "...", "confidence": 0.0-1.0, "product_data": {"name": "...", "price": null|number, "description": "...", "brand": null|"...", "category": "..."}|null}

Solo incluye product_data para classification="product". Responde SOLO el JSON array, sin markdown ni explicaciones.`;

return [{ json: { prompt, posts, userId: body.userId } }];

